WITH base AS (SELECT id, customer_id, device, browser, CONCAT_WS('/', browser, country) AS browser_country_key, COALESCE(browser, 'Unknown') AS browser_filled, COALESCE(browser, 'N/A') AS resolved_browser FROM sessions WHERE started_at >= TIMESTAMP '2024-01-07 03:00:00' AND browser IS NOT NULL AND country IN ('TH', 'JP')) SELECT customer_id, SORT_ARRAY(COLLECT_SET(device)) AS device_list, SIZE(COLLECT_SET(browser)) AS num_browsers, COUNT(*) FILTER (WHERE browser = 'Safari') AS safari_rows, SIZE(COLLECT_SET(browser)) AS num_browsers_2, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) FILTER (WHERE browser = 'Safari') AS safari_rows_2 FROM base GROUP BY customer_id
